# (feastDate, English name, Turkish name, Turkish description, Turkish patronOf) - the original English seed saints, first part
DATA = [
    ("March 19", "Saint Joseph", "Aziz Yusuf", "İşçilerin, evrensel Kilise'nin ve babaların koruyucusu. Kutsal Bakire Meryem'in eşi ve İsa'nın evlat edinen babası. Nasıra'da marangozdu; Kutsal Aile'yi Mısır'a kaçışları sırasında korudu ve Tanrı'nın Oğlu'nu sevgi ve alçakgönüllülükle büyüttü.", "İşçiler, babalar, aileler, Kilise, ölmek üzere olanlar"),
    ("March 17", "Saint Patrick", "Aziz Patrick", "Beşinci yüzyılda Hıristiyanlığı İrlanda halkına getirmesiyle tanınan İrlanda'nın koruyucu azizi. Roma Britanyası'nda doğdu, İrlandalı korsanlarca yakalanıp köle edildi. Kaçtıktan sonra piskopos olarak dönüp İrlanda'ya müjdeyi yaydı.", "İrlanda, mühendisler, dışlanmış insanlar"),
    ("October 4", "Saint Francis of Assisi", "Assisi'li Aziz Francis", "Fransiskan tarikatının kurucusu; yoksulluğun ve doğanın âşığı. 1224'te Mesih'in yaraları olan stigmataları aldı. Güneş İlahisi, İtalyan edebiyatının bilinen ilk eserlerinden biridir.", "Hayvanlar, ekoloji, tüccarlar, İtalya"),
    ("October 15", "Saint Teresa of Ávila", "Ávila'lı Aziz Teresa", "Kilise Doktoru ve mistik. Karmelit tarikatını ıslah etti; İç Şato ve Mükemmellik Yolu gibi derin ruhsal klasikler yazdı. Tefekkür duası üzerine öğretileri temel olmayı sürdürür.", "Baş ağrısı çekenler, İspanya, satranç oyuncuları"),
    ("June 13", "Saint Anthony of Padua", "Padovalı Aziz Anthony", "Kilise Doktoru, Fransiskan keşiş ve en sevilen azizlerden biri. Güçlü vaazları ve mucizeleriyle bilinir. Kayıp eşyaları bulmak ve yoksullara yardım için ona yakarılır.", "Kayıp eşyalar, yoksullar, yolcular, Portekiz, Brezilya"),
    ("June 29", "Saint Peter the Apostle", "Havari Aziz Petrus", "İsa'nın Göklerin Egemenliği'nin anahtarlarını verdiği havarilerin önderi. Roma'nın ilk piskoposu ve ilk papa. İmparator Nero döneminde yaklaşık 64-68'de baş aşağı çarmıha gerilerek şehit edildi.", "Balıkçılar, papalık, ağ yapımcıları, Roma"),
    ("June 29", "Saint Paul the Apostle", "Havari Aziz Pavlus", "Uluslara havari, misyoner ve Yeni Antlaşma'nın büyük bir bölümünün yazarı. Tarsuslu Saul olarak doğdu; Şam yolundaki çarpıcı dönüşümünden önce ilk Hıristiyanlara zulmetti. Akdeniz dünyasını dolaşıp kiliseler kurdu.", "Yazarlar, ilahiyatçılar, misyonerler, Yunanistan"),
    ("July 22", "Saint Mary Magdalene", "Aziz Magdalalı Meryem", "İsa Mesih'in sadık bir öğrencisi. İsa'nın çarmıha gerilişinde ve gömülüşünde hazır bulundu ve dirilişe ilk tanık oldu; bu yüzden 'Havarilere Havari' unvanını kazandı.", "Tefekkür edenler, kadınlar, parfümcüler, din değiştirenler"),
    ("August 28", "Saint Augustine of Hippo", "Hippo'lu Aziz Augustinus", "Kilise Doktoru ve filozof. Otobiyografisi İtiraflar, tarihin en büyük ruhsal yazılarındandır. Dönüşümünden önce günahla derinden boğuştu ve şöyle yazdı: 'Yüreğimiz sende huzur bulana dek huzursuzdur.'", "İlahiyatçılar, bira üreticileri, matbaacılar, göz ağrısı çekenler"),
    ("October 1", "Saint Thérèse of Lisieux", "Lisieux'lü Aziz Thérèse", "'Küçük Çiçek'; 15 yaşında Karmel'e girdi, 24'te veremden öldü. Otobiyografisi Bir Ruhun Hikâyesi, 'küçük yolu' - küçük şeyleri büyük sevgiyle yapmak - dünya çapında Katolik maneviyatını dönüştürdü.", "Misyonlar, Fransa, AIDS hastaları, çiçekçiler"),
    ("December 6", "Saint Nicholas", "Aziz Nikolaos", "Yoksullara cömertliğiyle tanınan dördüncü yüzyıl Myra piskoposu. Üç yoksul kız kardeş için gizlice çeyiz sağladı, geceleri pencereden altın keseleri attı; bu hikâye Noel Baba efsanesine ilham verdi.", "Çocuklar, denizciler, tüccarlar, Rusya"),
    ("June 24", "Saint John the Baptist", "Vaftizci Aziz Yahya", "İsa Mesih'in peygamberi ve öncüsü. İsa'yı Ürdün Nehri'nde vaftiz etti, 'İşte Tanrı'nın Kuzusu!' diye haykırdı. Salome'nin isteği üzerine Herodes Antipas tarafından başı kesildi.", "Vaftiz, Ürdün, terziler, nalbantlar"),
    ("April 29", "Saint Catherine of Siena", "Sienalı Aziz Catherine", "Kilise Doktoru, mistik ve siyasi reformcu. Papa XI. Gregorius'u papalığı Avignon'dan Roma'ya geri taşımaya başarıyla ikna etti. Ruhsal başyapıtı Diyalog, mistik ilahiyatın bir hazinesi olmayı sürdürür.", "İtalya, hemşireler, yangından korunma, Roma"),
    ("July 31", "Saint Ignatius of Loyola", "Loyola'lı Aziz Ignatius", "İsa Cemiyeti'nin (Cizvitler) kurucusu. Savaş yaralarından iyileşirken ruhsal bir dönüşüm yaşayan İspanyol asker; dünya çapında hâlâ kullanılan 30 günlük dua programı Ruhsal Alıştırmalar'ı yazdı.", "Cizvitler, askerler, inzivalar, İspanya"),
    ("August 8", "Saint Dominic", "Aziz Dominic", "Vaizler Tarikatı'nın (Dominikanlar) kurucusu ve Tespih'in destekçisi. Sapkınlıkla zorla değil hakikatle mücadele etmek için vaaz ve bilgiye adanmış dilenci bir tarikat kurdu.", "Astronomlar, haksız suçlananlar, bilim insanları"),
    ("August 11", "Saint Clare of Assisi", "Assisi'li Aziz Clare", "Fakir Hanımlar Tarikatı'nın (Fakir Clare'ler) kurucusu. Assisi'li Francis'ten ilham alarak köklü yoksulluğu benimsedi. Hasta olduğu için gidemediği Noel Ayini'ni hücresinin duvarında gördüğü söylendiği için televizyonun koruyucusudur.", "Televizyon, göz hastalıkları, iğne işi yapanlar"),
    ("October 22", "Saint John Paul II", "Aziz Yuhanna Pavlus II", "1978'den 2005'e papa; tarihin en çok seyahat eden ve en etkili papalarından biri. Polonya'da Komünizmin sona ermesinde belirleyici bir rol oynadı. Çok sayıda ansiklik yazdı ve önceki tüm papalardan daha fazla kişiyi mübarek ve aziz ilan etti.", "Dünya Gençlik Günü, Polonya"),
    ("July 11", "Saint Benedict of Nursia", "Nursia'lı Aziz Benedictus", "Batı manastırcılığının ve Benedikten Tarikatı'nın kurucusu. Keşişleri ora et labora (dua et ve çalış) yaşamına çağıran Aziz Benedictus Kuralı, Batı Kilisesi'nde manastır yaşamının temeli oldu.", "Avrupa, öğrenciler, keşişler, çiftçiler"),
    ("October 18", "Saint Luke the Evangelist", "Müjdeci Aziz Luka", "Hekim, Pavlus'un arkadaşı ve üçüncü İncil ile Elçilerin İşleri'nin yazarı. İncili merhamet, Kutsal Ruh, dua ve kadınların rolünü vurgular. Gelenek, Meryem'in ilk ikonunu onun yaptığını söyler.", "Hekimler, cerrahlar, sanatçılar, ressamlar"),
    ("December 27", "Saint John the Evangelist", "Müjdeci Aziz Yuhanna", "'Sevgili öğrenci' ve en genç havari. Dördüncü İncil'in, üç mektubun ve Vahiy Kitabı'nın yazarı. Haçın dibinde durdu ve Meryem'in bakımı ona emanet edildi.", "Yazarlar, ilahiyatçılar, sanat tüccarları, Türkiye"),
    ("December 26", "Saint Stephen", "Aziz Stephanos", "İlk Hıristiyan şehit. Havariler tarafından seçilen yedi diyakozdan biri; Sanhedrin önünde güçlü bir konuşma yaptıktan sonra taşlanarak öldürüldü. Tarsuslu Saul (sonradan Pavlus) onun şehitliğine tanık oldu.", "Diyakozlar, taş ustaları, baş ağrısı çekenler"),
    ("February 14", "Saint Valentine", "Aziz Valentinus", "269'da şehit edilen Romalı rahip ve hekim. Tarihsel ayrıntı az bilinse de aşk ve şövalyece romantizmle anılır. Bayramı, on dördüncü yüzyıl İngiliz şiirinde romantik aşkla ilişkilendirildi.", "Aşk, nişanlı çiftler, mutlu evlilikler, arıcılar"),
    ("July 25", "Saint Christopher", "Aziz Christopher", "Bir çocuğu nehrin karşısına taşıyan, çocuğun dünyanın yükünü taşıyan Mesih olduğunu anlayan dev bir adam. Adı 'Mesih'i taşıyan' anlamına gelir. 1969'da genel Roma takviminden çıkarılsa da sevilmeyi sürdürür.", "Yolcular, sürücüler, sörfçüler, fırtınalar"),
    ("August 15", "Blessed Virgin Mary (Assumption)", "Kutsal Bakire Meryem (Göğe Alınış)", "Meryem'in Göğe Alınışı, onun beden ve ruh olarak göksel yüceliğe alındığı dogmasını kutlar. Kilise'nin en eski bayramlarından biridir; çoğu ülkede kutsal yükümlülük günü olarak büyük törenle kutlanır.", "Tüm insanlık, Kilise"),
    ("January 28", "Saint Thomas Aquinas", "Aquinolu Aziz Thomas", "Kilise Doktoru ve Orta Çağ'ın en büyük ilahiyatçısı. Başyapıtı Summa Theologiae, Aristoteles felsefesini Hıristiyan ilahiyatıyla birleştirdi ve Katolik entelektüel geleneğinin temeli olmayı sürdürür.", "Öğrenciler, okullar, üniversiteler, İtalya"),
    ("September 5", "Saint Teresa of Calcutta", "Kalküta'lı Aziz Teresa", "Sevgi Misyonerleri'nin kurucusu. Hayatını Kalküta gecekondularındaki yoksulların en yoksuluna adadı. 'Hepimiz büyük işler yapamayız. Ama küçük şeyleri büyük sevgiyle yapabiliriz' sözü dünya çapında yankılanır.", "Dünya Gençlik Günü, Sevgi Misyonerleri"),
    ("April 23", "Saint George", "Aziz George", "Üçüncü yüzyıldan beri onurlandırılan askerî şehit. Bir prensesi kurtarmak için ejderhayı öldürme efsanesi, iyiliğin kötülüğe ve imanın korkuya karşı zaferini simgeler. İngiltere, Gürcistan ve diğer birçok ulusun koruyucusudur.", "İngiltere, askerler, izciler, çiftçiler"),
    ("November 17", "Saint Elizabeth of Hungary", "Macaristanlı Aziz Elisabeth", "Yoksullara bakmak için saray yaşamını bırakan Macar prensesi. 20 yaşında dul kalınca Üçüncü Fransiskan Tarikatı'na katıldı ve kalan yıllarını hastalara ve yoksullara hizmetle geçirdi; 24 yaşında öldü.", "Yoksullar, hastaneler, fırıncılar, hemşireler"),
    ("October 5", "Saint Faustina Kowalska", "Aziz Faustina Kowalska", "Polonyalı mistik ve İlahi Merhamet'in havarisi. Günlüğü, İlahi Merhamet Ruhumda, İsa'nın ondan merhametinin mesajını yaymasını istediği vizyonları kaydeder. İlahi Merhamet bağlılığı bugün dünyada milyonlara ulaşır.", "Merhamet, Polonya, İlahi Merhamet bağlılığı"),
    ("September 29", "Archangel Michael", "Başmelek Mikail", "Meleklerin başı, Kilise'nin savunucusu ve askerlerin koruyucusu. Vahiy Kitabı'nda şeytanın yenilgisinde göksel orduya önderlik eder. Aziz Mikail Duası birçok kilisede Ayin'den sonra okunur.", "Askerler, polis, sağlık görevlileri, bakkallar"),
    ("October 28", "Saint Jude Thaddeus", "Aziz Yahuda Thaddeus", "İsa Mesih'in havarisi; geleneksel olarak Küçük Yakup'un kardeşi ve İsa'nın akrabası sayılır. Yahuda Mektubu'nun yazarıdır ve Yahudiye, Samiriye, Idumea, Suriye, Mezopotamya ve Libya'da müjdeyi vaaz ettiğine, şehit olarak öldüğüne inanılır.", "Umutsuz davalar, çaresiz durumlar, hastaneler"),
    ("May 22", "Saint Rita of Cascia", "Cascia'lı Aziz Rita", "'İmkânsızın Azizi' olarak bilinen Augustinian rahibe. Zor bir evlilikten ve oğullarının ölümünden sonra dul kalıp İtalya'daki Cascia manastırına girdi. Alnında Diken Taç'a benzeyen bir yara aldı ve ölümüne dek taşıdı.", "İmkânsız davalar, zor evlilikler, dullar, istismar mağdurları"),
    ("August 14", "Saint Maximilian Kolbe", "Aziz Maximilian Kolbe", "1941'de Auschwitz toplama kampında bir yabancının, bir koca ve babanın yerine ölmeye gönüllü olan Polonyalı Fransiskan keşiş. 1982'de Papa Yuhanna Pavlus II tarafından sevgi şehidi olarak aziz ilan edildi. Hapsedilmeden önce Lekesiz Meryem'e adanmış bir Fransiskan topluluğu kurmuştu.", "Gazeteciler, aileler, mahkûmlar, yaşam yanlısı hareket"),
    ("September 23", "Saint Pio of Pietrelcina (Padre Pio)", "Pietrelcina'lı Aziz Pio (Padre Pio)", "Elli yıl boyunca Mesih'in Çilesi'nin görünür yaraları olan stigmataları taşıyan İtalyan Kapuçin rahip ve mistik. Uzun saatler günah çıkarma dinlemesi ve ruhsal ayırt etme armağanıyla tanındı; 'Acıyı Hafifletme Evi' hastanesini kurdu. 2002'de Papa Yuhanna Pavlus II tarafından aziz ilan edildi.", "Günah çıkarıcılar, sivil savunma gönüllüleri, ergenler, stresin hafiflemesi"),
    ("August 4", "Saint John Vianney", "Aziz John Vianney", "Ars Papazı olarak bilinen Fransız köy rahibi; günde on altı saate kadar günah çıkarma dinleyerek gösterdiği olağanüstü gayretle ünlüdür. Eğitiminde başlangıçta zorlansa da kutsallığı, tövbesi ve ruhların çobanlığı ile tanındı. 1925'te Papa XI. Pius tarafından aziz ilan edildi.", "Köy rahipleri, günah çıkarıcılar"),
    ("April 16", "Saint Bernadette Soubirous", "Aziz Bernadette Soubirous", "Fransa'daki Lourdes'tan yoksul bir değirmencinin kızı; 1858'de Massabielle Mağarası'nda Kutsal Bakire Meryem'in on sekiz görünüşünü bildirdi. Sonra Nevers'de Sevgi Rahibesi oldu ve ölümüne dek alçakgönüllülük ve acı dolu gizli bir hayat sürdü. 1933'te Papa XI. Pius tarafından aziz ilan edildi.", "Lourdes, hastalar, çoban kızlar"),
    ("July 14", "Saint Kateri Tekakwitha", "Aziz Kateri Tekakwitha", "1656'da bugünkü New York'ta doğan Mohawk-Algonquin kadın; ailesinin ve köyünün zulmüne rağmen genç yaşta Katolikliğe geçti ve sonsuz bekâret yemini etti. 'Mohawkların Zambağı' olarak bilinir ve 2012'de Papa XVI. Benedictus tarafından aziz ilan edilen ilk Kızılderilidir.", "Ekoloji, Kızılderililer, sürgünler"),
    ("October 12", "Saint Carlo Acutis", "Aziz Carlo Acutis", "Kutsal Efkaristiya'ya derin bağlılığı ve bilgisayar becerisiyle tanınan İtalyan genç; bunu dünyadaki Efkaristiya mucizelerini listeleyen bir web sitesi kurmak için kullandı. 2006'da on beş yaşında lösemiden öldü ve acılarını Kilise için sundu. 2020'de mübarek, 2025'te Papa XIV. Leo tarafından aziz ilan edildi.", "İnternet, bilgisayar programcıları, gençler"),
    ("November 22", "Saint Cecilia", "Aziz Cecilia", "Erken Kilise'nin Romalı bakire şehidi; geleneğe göre düğün gününde yüreğinde göksel müzik duydu ve bekâretini Tanrı'ya adadı. İmanı yüzünden şehit edildi ve erken Roma şehitlerinin en çok onurlandırılanlarındandır.", "Müzisyenler, şarkıcılar, besteciler, kilise müziği"),
    ("December 13", "Saint Lucy", "Aziz Lucy", "Diocletianus zulmü sırasında dördüncü yüzyılın başında ölen Sicilya'daki Syrakusa bakire şehidi. Bekâretini Tanrı'ya adadı ve ihanete uğrayıp öldürülmeden önce çeyizini yoksullara dağıttı. 'Işık' anlamındaki adı onu uzun zamandır görme duasıyla ilişkilendirmiştir.", "Körler, görme, Syrakusa"),
    ("August 27", "Saint Monica", "Aziz Monica", "Hippo'lu Aziz Augustinus'un annesi; zor bir evliliğe dayandı ve oğlunun dönüşümü için on yedi yıl gözyaşlarıyla dua etti; dönüşüm sonunda Milano'da Aziz Ambrosius'un vaazı sayesinde geldi. Augustinus'un vaftizine tanık olduktan kısa süre sonra Ostia'da öldü.", "Anneler, eşler, istismar mağdurları, sabır"),
    ("September 30", "Saint Jerome", "Aziz Jerome", "Papa I. Damasus'un daveti üzerine Eski ve Yeni Antlaşma'yı Latince'ye çevirip Vulgata'yı üreten Kilise Doktoru. Keskin mizacıyla ünlü bir bilgin ve çileciydi; son on yıllarını Beytüllahim yakınındaki bir mağarada çalışma ve duaya adayarak geçirdi.", "Kutsal Kitap bilginleri, çevirmenler, kütüphaneciler"),
    ("August 23", "Saint Rose of Lima", "Lima'lı Aziz Rose", "Üçüncü Dominikan Tarikatı üyesi Perulu mistik; Amerika'da doğan ilk aziz ilan edilen kişi. Memleketi Lima'da hastalara, yoksullara ve yaşlılara bakarken büyük tövbe ve dua dolu bir hayat sürdü.", "Peru, Latin Amerika, çiçekçiler, nakışçılar"),
    ("September 27", "Saint Vincent de Paul", "Aziz Vincent de Paul", "Hayatını yoksullara ve hastalara hizmete adayan 'Sevginin Havarisi' Fransız rahip. Misyon Cemaati'ni ve Aziz Louise de Marillac ile birlikte Sevgi Kızları'nı kurdu. 1737'de aziz ilan edildi.", "Hayır dernekleri, hastaneler, mahkûmlar, gönüllüler"),
    ("April 28", "Saint Gianna Beretta Molla", "Aziz Gianna Beretta Molla", "Hayatını kurtaracak ama doğmamış çocuğunu feda edecek tedaviyi kabul etmek yerine tehlikeli bir hamileliği sürdürmeyi seçen İtalyan çocuk doktoru, eş ve anne. Kızını doğurduktan bir hafta sonra 1962'de öldü. 2004'te Papa Yuhanna Pavlus II tarafından aziz ilan edildi.", "Anneler, hekimler, doğmamış çocuklar"),
    ("November 3", "Saint Martin de Porres", "Aziz Martin de Porres", "1579'da Lima'da doğan, Afrikalı ve İspanyol karışımı kökenli Perulu Dominikan kardeş. Çağının ırk önyargısına rağmen alçakgönüllülüğü, şifa armağanları ve hastalara, yoksullara ve köleleştirilenlere yorulmaz bakımıyla tanındı. 1962'de Papa XXIII. Yuhanna tarafından aziz ilan edildi.", "Karışık ırktan insanlar, berberler, halk sağlığı çalışanları, sosyal adalet"),
    ("February 8", "Saint Josephine Bakhita", "Aziz Josephine Bakhita", "Çocukken kaçırılıp köle olarak satılan, İtalya'da özgürlüğüne kavuşan ve Canossian Sevgi Kızları'na katılan Sudanlı kadın. Eski esircilerine karşı dinginliği ve bağışlayıcılığıyla tanındı ve on yıllarca topluluğuna alçakgönüllü hizmet etti. 2000'de Papa Yuhanna Pavlus II tarafından aziz ilan edildi.", "Sudan, insan ticareti mağdurları, kaçırılmadan kurtulanlar"),
    ("July 4", "Saint Pier Giorgio Frassati", "Aziz Pier Giorgio Frassati", "Neşeli imanı, dağcılığa sevgisi ve Torino yoksullarına yorulmaz hizmetiyle tanınan İtalyan meslekten olmayan kişi. Üçüncü Dominikan Tarikatı üyesiydi; 1925'te 24 yaşında çocuk felcinden öldü, muhtemelen hastalara bakarken kaptı. 2025'te Papa XIV. Leo tarafından aziz ilan edildi.", "Gençler, dağcılar, Dünya Gençlik Günü"),
    ("January 31", "Saint John Bosco", "Aziz John Bosco", "Torino'daki yoksul ve terk edilmiş erkek çocukların eğitimine ve bakımına hayatını adayan İtalyan rahip ve Don Bosco Salezyenleri'nin kurucusu. 'Gençliğin Babası ve Öğretmeni' olarak bilinen kendisi, gençleri yetiştirmede iman, akıl ve nezaketi birleştirdi. 1934'te Papa XI. Pius tarafından aziz ilan edildi.", "Gençler, çıraklar, editörler, sihirbazlar"),
    ("January 4", "Saint Elizabeth Ann Seton", "Aziz Elizabeth Ann Seton", "Amerika Birleşik Devletleri'nde doğan ve aziz ilan edilen ilk kişi. Beş çocukla dul kalınca Katolikliğe geçti, Aziz Joseph Sevgi Rahibeleri'ni kurdu ve Maryland'in Emmitsburg kentinde Amerika'nın ilk ücretsiz Katolik kız okulunu açtı. 1975'te Papa VI. Paulus tarafından aziz ilan edildi.", "Katolik okulları, dullar, din değiştirenler"),
    ("July 6", "Saint Maria Goretti", "Aziz Maria Goretti", "1902'de on bir yaşında bir cinsel saldırıya direnirken şehit edilen İtalyan kız; yaralarından ölmeden önce saldırganını affetti, saldırgan sonradan onu bir vizyonda görüp tövbe etti. Annesinin hazır bulunduğu bir törenle 1950'de Papa XII. Pius tarafından aziz ilan edildi.", "Gençler, saflık, saldırı mağdurları"),
    ("December 3", "Saint Francis Xavier", "Aziz Francis Xavier", "Aziz Ignatius of Loyola ile birlikte İsa Cemiyeti'nin kurucu ortağı olan İspanyol Cizvit rahip. Hindistan, Güneydoğu Asya ve Japonya'da kapsamlı misyon yolculukları yaptı, binlerce kişiyi vaftiz etti ve 1552'de anakaraya girişi beklerken Çin kıyısındaki bir adada öldü. 1622'de Papa XV. Gregorius tarafından aziz ilan edildi.", "Misyonerler, yabancı misyonlar, denizciler"),
    ("May 26", "Saint Philip Neri", "Aziz Philip Neri", "'Roma'nın Havarisi' olarak bilinen, neşeli kutsallığı, mizahı ve günah çıkarma dinlemedeki yorulmaz çalışmasıyla ünlü İtalyan rahip. Meslekten olmayanlar ve din adamları arasında dua, vaaz ve cemaati geliştirmek için Oratory Cemaati'ni kurdu. 1622'de Papa XV. Gregorius tarafından aziz ilan edildi.", "Roma, sevinç, Oratoryenler"),
    ("July 26", "Saint Anne", "Aziz Anna", "Kutsal Bakire Meryem'in annesi ve İsa Mesih'in büyükannesi. Eski Hıristiyan geleneğine göre eşi Joachim ile yaşlı ve çocuksuz bir çift olup yıllarca süren hararetli duanın ardından Meryem'e gebe kaldılar. Sadık annelik örneği olarak onurlandırılır ve özellikle Quebec ve Bretagne'de saygı görür.", "Anneler, büyükanneler, ev kadınları, doğum yapan kadınlar, Quebec"),
    ("January 21", "Saint Agnes of Rome", "Romalı Aziz Agnes", "Yaklaşık 304'te Diocletianus zulmü sırasında şehit edilen genç Romalı bakire; geleneğe göre Mesih'e adanmışlığından vazgeçmeyi reddettiği için öldürüldüğünde sadece on iki ya da on üç yaşındaydı. Ayin'in Roma Kanonu'nda adı anılan yedi kadından biridir.", "Bakireler, iffet, genç kızlar, tecavüz mağdurları, bahçıvanlar"),
    ("November 13", "Saint Frances Xavier Cabrini", "Aziz Frances Xavier Cabrini", "1889'da Papa XIII. Leo'nun isteğiyle İtalyan göçmenlere hizmet etmek için Amerika Birleşik Devletleri'ne göç eden İtalya doğumlu rahibe. İsa'nın Kutsal Kalbi Misyoner Rahibeleri'ni kurdu ve Amerika ile Avrupa'da onlarca okul, hastane ve yetimhane kurdu. ABD vatandaşlığına geçti ve 1946'da Papa XII. Pius tarafından aziz ilan edilen ilk Amerikan vatandaşıdır.", "Göçmenler, hastane yöneticileri"),
    ("December 14", "Saint John of the Cross", "Haçlı Aziz Yuhanna", "İspanyol Karmelit keşiş, mistik ve Kilise Doktoru. Ávila'lı Aziz Teresa ile birlikte Karmelit Tarikatı'nı ıslah etti ve Çıplak Ayaklı Karmelitleri kurdu. Islaha karşı çıkan keşişlerce hapsedilip zulüm görürken ünlü mistik şiiri 'Ruhun Karanlık Gecesi'ni esaret sırasında besteledi.", "Mistikler, tefekkür edenler, İspanyol şairler"),
    ("May 10", "Saint Damien of Molokai", "Molokai'li Aziz Damien", "Hawaii'de Molokai Adası'ndaki Kalaupapa yerleşkesine sürgün edilen cüzzam hastalarına hizmet etmek için gönüllü olan Kutsal Kalpler Cemaati'nden Belçikalı rahip. Onlarla on altı yıl yaşadı, evler, bir kilise ve bir hastane inşa etti, sonra kendisi cüzzama yakalanıp 1889'da öldü. 2009'da Papa XVI. Benedictus tarafından aziz ilan edildi.", "Cüzzamlılar, dışlanmışlar, Hawaii, HIV/AIDS hastaları"),
    ("November 30", "Saint Andrew the Apostle", "Havari Aziz Andreas", "Aziz Petrus'un kardeşi ve Beytsayda'lı bir balıkçı; Vaftizci Yahya'nın öğrencisiydi, sonra İsa'nın çağırdığı On İkiler'in ilki oldu ve 'Protoklet' ('ilk çağrılan') unvanını aldı. Gelenek, Yunanistan ve Küçük Asya'da vaaz verdiğini ve Patras'ta bugün Aziz Andreas Haçı denen X biçimli bir çarmıha bağlanarak şehit edildiğini söyler.", "İskoçya, Rusya, Yunanistan, balıkçılar"),
    ("July 3", "Saint Thomas the Apostle", "Havari Aziz Tomas", "On İki Havari'den biri; Mesih'in yaralarına dokunana dek dirilişe inanmayı reddettiği için 'Şüpheci Tomas' olarak anılır; sonra 'Rabbim ve Tanrım' diye itiraf etti. Gelenek, onun İncil'i Hindistan'a taşıdığını ve Kerala'daki Aziz Tomas Hıristiyanlarının kökeninin ona dayandığını, orada şehit edildiğini söyler.", "Hindistan, mimarlar, şüphe edenler"),
    ("August 24", "Saint Bartholomew the Apostle", "Havari Aziz Bartholomeos", "Çoğunlukla İsa'nın 'gerçekten bir İsrailli, içinde hile yok' dediği Nathanael ile özdeşleştirilen On İki Havari'den biri. Gelenek, Ermenistan'da müjdeyi vaaz ettiğini ve derisi yüzülerek şehit edildiğini söyler; bu yüzden sanatta kendi derisini tutarken tasvir edilir.", "Derici, deri işçileri, Ermenistan"),
    ("September 21", "Saint Matthew the Apostle", "Havari Aziz Matta", "İsa'nın 'Beni izle' diyerek çağırdığında gümrük kapısında oturan bir vergi görevlisi; her şeyi bırakıp On İki Havari'den biri oldu. Geleneksel olarak Matta İncili'nin yazarı sayılır.", "Muhasebeciler, bankacılar, vergi görevlileri"),
    ("July 25", "Saint James the Greater", "Büyük Aziz Yakup", "Zebedi'nin oğlu ve Müjdeci Yuhanna'nın kardeşi; İsa'nın kardeşiyle birlikte çağırdığı bir balıkçı. Başkalaşım ve Bahçe'deki Ağıt'ta hazır bulunan üç havariden biri olan o, On İkiler'den ilk şehit olup yaklaşık 44'te I. Herodes Agrippa tarafından başı kesildi. Santiago de Compostela'daki mezarı Hıristiyan dünyasının büyük hac merkezlerinden biri oldu.", "İspanya, hacılar, işçiler"),
    ("June 11", "Saint Barnabas", "Aziz Barnaba", "Aslen Yusuf adlı bir Kıbrıslı Levili; mülkünü satıp parasını erken Kilise'ye verdikten sonra havarilerce 'Barnaba' ('cesaret oğlu') adını aldı. Yeni dönmüş Tarsuslu Saul'u havarilere tanıttı ve onunla ilk misyon yolculuğuna çıktı. On İkiler'den biri olmasa da Havari unvanıyla onurlandırılır.", "Kıbrıs, barış yapıcılar"),
    ("September 13", "Saint John Chrysostom", "Aziz Yuhanna Chrysostomos", "Kilise Doktoru ve İstanbul Başpiskoposu; hitabetiyle 'Chrysostom' ('Altın ağızlı') lakabını kazandı. Kutsal Kitap üzerine vaazları ve yoksullar için ıslahçı gayreti imparatorluk sarayını öfkelendirdi; sürgüne gönderildi ve 407'de orada öldü. Aziz Yuhanna Chrysostomos'un İlahi Litürjisi Bizans Ayini'nin başlıca litürjisi olarak kalmıştır.", "Vaizler, hatipler, İstanbul"),
    ("December 7", "Saint Ambrose", "Aziz Ambrosius", "Kilise Doktoru ve Milano Piskoposu; vaftiz edilmemiş bir hıristiyan adayıyken halkın alkışıyla görevi üstlenmek üzere seçilen eski bir Romalı vali. Yetenekli bir vaiz ve ilahi yazarı olarak Aziz Augustinus'u eğitti ve vaftiz etti, Arius'çuluğa ve imparatorluğun Kilise işlerine müdahalesine kararlılıkla karşı çıktı. 397'de öldü.", "Milano, arıcılar, öğrenme"),
    ("January 2", "Saint Basil the Great", "Büyük Aziz Basil", "Kilise Doktoru ve Kapadokya'daki Kayseri Piskoposu; İznik inancını Ariusçuluğa karşı savunan büyük Kapadokyalı Babalar'dan biri. Doğu manastırcılığını şekillendiren bir manastır kuralı yazdı, yoksullar ve hastalar için bir hayır kurumları kompleksi kurdu ve bu bayramda Nazianzos'lu Aziz Gregory ile birlikte onurlandırılır.", "Hastane yöneticileri, keşişler, Kapadokya"),
    ("February 3", "Saint Blaise", "Aziz Blaise", "Dördüncü yüzyılın başında Licinius zulmü altında şehit edilen Ermenistan'daki piskopos ve hekim. Gelenek, balık kılçığından boğulan bir çocuğu mucizevi biçimde kurtardığını söyler; bu yüzden bayramında onun adıyla çapraz mumlarla boğazların kutsanması yapılır.", "Boğaz hastalıkları, yün tarayıcıları, veterinerler"),
    ("January 20", "Saint Sebastian", "Aziz Sebastianus", "Hıristiyan imanı nedeniyle İmparator Diocletianus altında şehit edilen Romalı asker. Okla vurulup ölüme terk edilmeye mahkûm edildi; Romalı Aziz Irene tarafından sağlığına kavuşturuldu ama imparatorla yüzleşmeye döndü ve sonra sopayla dövülerek öldürüldü. Hıristiyan sanatında en sık tasvir edilen azizlerdendir.", "Sporcular, askerler, okçular"),
    ("May 30", "Saint Joan of Arc", "Aziz Joan of Arc", "Azizlerin vizyonlarıyla yönlendirilerek Yüzyıl Savaşları sırasında Fransız ordusunu zafere taşıyan, sonra yakalanıp 1431'de yakılarak öldürülen Fransız köylü kızı. 1456'da yeniden yargılanıp aklandı ve 1920'de Papa XV. Benedictus tarafından aziz ilan edildi.", "Fransa, askerler, mahkûmlar"),
    ("May 15", "Saint Isidore the Farmer", "Çiftçi Aziz Isidore", "Dindarlığı, yoksullara hayırseverliği ve tarlada çalışırken bile günlük Ayin'e bağlılığıyla tanınan Madrid'li İspanyol çiftlik işçisi. Gelenek, meleklerin onun yanında sabanla çalıştığını görüldüğünü söyler. 1622'de Aziz Ignatius of Loyola, Francis Xavier, Ávila'lı Teresa ve Philip Neri ile birlikte aziz ilan edildi.", "Çiftçiler, işçiler, Madrid"),
    ("August 1", "Saint Alphonsus Liguori", "Aziz Alphonsus Liguori", "Kırsal yoksullar arasında misyon vaazlarına adanmış Redemptoristler'i (En Kutsal Kurtarıcı Cemaati) kuran İtalyan piskopos ve ahlak ilahiyatçısı. Ahlak ilahiyatı üzerine bereketli yazıları katılığın yerine merhameti vurguladı. 1871'de Kilise Doktoru ilan edildi.", "Günah çıkarıcılar, ahlak ilahiyatçıları, Redemptoristler"),
    ("January 24", "Saint Francis de Sales", "Aziz Francis de Sales", "Ruhlara rehberlikteki nazik ve sabırlı yaklaşımı nedeniyle 'Beyefendi Aziz' olarak bilinen Cenevre Piskoposu ve Kilise Doktoru. Aziz Jane Frances de Chantal ile Ziyaret Tarikatı'nı kurdu; klasik eseri Dindar Yaşama Giriş, gündelik hayatta kutsallık maneviyatını sıradan meslekten olmayan insanlara ulaştırdı. 1923'te Papa XI. Pius tarafından yazarların ve gazetecilerin koruyucusu ilan edildi.", "Yazarlar, gazeteciler, Katolik basını, eğitimciler"),
    ("March 8", "Saint John of God", "Tanrı'nın Aziz Yuhannası", "Hastanelere Adanmış Kardeşler Tarikatı'nın (Aziz Yuhanna Hastane Kardeşleri) Portekiz doğumlu kurucusu. İspanya'nın Granada kentinde çarpıcı bir dinî dönüşümün ardından hayatının kalanını hastalara, yoksullara ve evsizlere bakmaya adadı ve tarikatının modeli olan bir hastane açtı. 1690'da Papa VIII. Alexander tarafından aziz ilan edildi.", "Hastaneler, hemşireler, hastalar, kitapçılar, matbaacılar"),
    ("July 23", "Saint Bridget of Sweden", "İsveçli Aziz Bridget", "Aralarında İsveçli Aziz Catherine'in de bulunduğu sekiz çocuklu İsveçli mistik, eş ve anne. Kocasının ölümünden sonra Bridgettine Tarikatı'nı (En Kutsal Kurtarıcı Tarikatı) kurdu ve mistik vizyonlarını Vahiyleri'nde kaydetti. 1391'de aziz ilan edildi ve 1999'da Papa Yuhanna Pavlus II tarafından Avrupa'nın eş koruyucusu ilan edildi.", "İsveç, Avrupa, dullar"),
    ("October 17", "Saint Ignatius of Antioch", "Antakyalı Aziz Ignatius", "Havarisel Baba ve Antakya'nın üçüncü piskoposu; geleneksel olarak Havari Yuhanna'nın öğrencisi sayılır. İmparator Traianus altında mahkûm edilip Roma'da Kolezyum'da vahşi hayvanlarca şehit edilmek üzere götürüldü ve yolculuk boyunca Hıristiyan topluluklarına, erken Kilise'nin en eski ve en değerli belgeleri arasında yer alan yedi mektup yazdı.", "Antakya, piskoposlar"),
    ("February 23", "Saint Polycarp", "Aziz Polycarp", "İzmir Piskoposu ve Havari Yuhanna'nın öğrencisi; havariler çağını onları izleyen büyük Kilise Babaları'na bağlayan Havarisel Babalar'dan biri. Kamusal bir zulüm sırasında Mesih'e lanet etmesi ve bağışlanması emredildiğinde, seksen altı yıldır Mesih'e hizmet ettiğini ve şimdi O'nu inkâr etmeyeceğini söyleyerek reddetti; yaklaşık 155'te kazığa bağlanıp yakıldı.", "İzmir, kulak ağrısı çekenler, dizanteri hastaları"),
    ("August 9", "Saint Edith Stein (Teresa Benedicta of the Cross)", "Aziz Edith Stein (Haçlı Teresa Benedicta)", "Edmund Husserl'in öğrencisi olan Alman Yahudi filozof; 1922'de Katolikliğe geçti ve Haçlı Teresa Benedicta adını alarak Çıplak Ayaklı Karmelit rahibe oldu. Hollandalı piskoposların Yahudi karşıtlığını kamuoyu önünde kınamasına misilleme olarak 1942'de Naziler tarafından tutuklandı ve Auschwitz'deki gaz odalarında öldü. 1998'de Papa Yuhanna Pavlus II tarafından aziz ilan edildi ve Avrupa'nın eş koruyucusu seçildi.", "Avrupa, din değiştirenler, şehitler"),
    ("November 23", "Blessed Miguel Pro", "Mübarek Miguel Pro", "Cristero Savaşı'ndaki Katolik karşıtı zulüm sırasında inananlara gizlice hizmet eden Meksikalı Cizvit rahip; ölüm tehlikesine rağmen Ayin yapmak ve ayinleri vermek için kılık değiştirdi. Asılsız bir suçlamayla tutuklanıp 1927'de yargılanmadan kurşuna dizildi; ölmeden önce kollarını haç biçiminde açıp 'Yaşasın Kral Mesih!' diye haykırdığı bildirilir. 1988'de Papa Yuhanna Pavlus II tarafından mübarek ilan edildi.", "Meksika, zulüm gören Hıristiyanlar, Meksikalı rahipler"),
    ("October 9", "Saint John Henry Newman", "Aziz John Henry Newman", "Anglikanizm içinde Oxford Hareketi'ne önderlik ettikten sonra 1845'te Katolik Kilisesi'ne kabul edilen İngiliz ilahiyatçı ve Oxford akademisyeni; ardından Birmingham Oratory'yi kurdu. Kardinal ve modern çağın en etkili Katolik düşünürlerinden biri olarak vicdan ve öğreti üzerine, otobiyografisi Apologia Pro Vita Sua dahil, kapsamlı yazılar yazdı. 2019'da Papa Franciscus tarafından aziz ilan edildi.", "Yazarlar, din değiştirenler, ilahiyatçılar, Katolik eğitimi"),
    ("March 3", "Saint Katharine Drexel", "Aziz Katharine Drexel", "Servetinden vazgeçerek Kızılderililer ve Siyahlar için Kutsal Ekmek Rahibeleri'ni kuran, hayatını ve mirasını Amerika Birleşik Devletleri genelinde Kızılderili ve Afro-Amerikalı topluluklar için misyonlar ve okullar kurmaya adayan Amerikalı mirasyedi. Afro-Amerikalılar için ABD'de ilk Katolik üniversitesi olan Louisiana'daki Xavier Üniversitesi'ni kurdu. 2000'de Papa Yuhanna Pavlus II tarafından aziz ilan edildi.", "Hayırseverler, ırksal adalet, Kızılderililer"),
]
